    "whoItServes": "हर वह सदस्य जिसके पास कुछ टूटा हुआ है और उसे ठीक कराने के लिए न पैसे हैं न हुनर; और काम की चीज़ें कूड़े के ढेर तक पहुँचने से बच जाती हैं।",
