    "setupHours": 14,
    "defaultCategory": "skilled_labor",
    "suggestsWorkDays": true,
    "firstSteps": "सबसे पहले अपने दो-तीन मरम्मत करने वाले जुटाएँ — वे पड़ोसी जो सिलाई करते हैं, वे जो साइकिलें ठीक करते रहते हैं — क्योंकि उनके बिना तारीख़ और जगह के कोई मायने नहीं। फिर उनके साथ मिलकर जगह घूमें और मेज़, बिजली और रोशनी पर बात करें, और आस-पास के किसी शहर में मरम्मत कैफ़े चलता हो तो उसकी एक बैठक देख आएँ; वहाँ से चुराने लायक़ चीज़ यही है — आने वालों और उनके सामान को दर्ज करके सही मेज़ तक पहुँचाने का तरीक़ा।",
