    "whatYoullNeed": "दान में आई किताबें, हाथ बँटाने वाले लोग, डाक ख़र्च, और हर जेल के डाक-नियमों की जानकारी। हर जेल के डाक-नियम सख़्त और अलग-अलग होते हैं — नियम तोड़ने वाले पार्सल लौटा दिए जाते हैं, इसलिए उन्हें हूबहू मानें, और मददगार हमेशा कार्यक्रम का पता ही लिखें, अपने घर का कभी नहीं।",
