    "name": "क़ानूनी मदद शिविर और “अपने हक़ जानें” कार्यक्रम",
    "purpose": "पड़ोसियों को मुफ़्त क़ानूनी मदद से जोड़ें और लोगों को उनके हक़ बताएँ।",
    "whoItServes": "हर वह शख़्स जो बिना साधनों के क़ानूनी मुश्किल में फँसा हो — मकान, प्रवास, पैसे की वसूली, परिवार या सरकारी मदद के मामले।",
    "whatYoullNeed": "मदद के लिए तैयार वकील और क़ानून के छात्र, एक जगह, क़ानूनी मदद करने वाली साथी संस्थाएँ, और तारीख़ों का इंतज़ाम। किसी एक मामले की क़ानूनी सलाह सिर्फ़ लाइसेंसधारी, क़ाबिल वकील (या उनकी निगरानी में काम कर रहे क़ानून के छात्र) ही दे सकते हैं — यह कार्यक्रम पहुँच जुटाता है और हक़ों की आम जानकारी बाँटता है, यह ख़ुद क़ानूनी सलाह का ज़रिया नहीं है।",
    "setupHours": 26,
    "defaultCategory": "other",
    "suggestsWorkDays": true,
    "firstSteps": "वकील साथ हुए बिना यहाँ कुछ शुरू नहीं होता: सबसे पहले पास के क़ानूनी मदद दफ़्तर, बार एसोसिएशन के मुफ़्त मदद कार्यक्रम और किसी लॉ कॉलेज के क़ानूनी मदद केंद्र को फ़ोन करें और पूछें कि आने के लिए उन्हें क्या चाहिए — और मोहल्ले का शिविर असल में कौन-सी कमी भर सकता है। पड़ोसियों को कुछ भी बताने से पहले इन्हीं साथियों के साथ मिलकर शिविर का दायरा तय करें।",
    "commonPitfalls": "ख़तरनाक चूक यह है कि कोई अपनापन रखने वाला मददगार जानकारी देते-देते सलाह देने लगे — नेक नीयत से कहा गया “आप बस दस्तख़त कर दें” किसी का पूरा मामला बिगाड़ सकता है, इसलिए यह लकीर साफ़ रखें और उसका अभ्यास कराएँ। धीमी चूक यह है कि नाम दर्ज होते जाएँ और वकील उतने न हों: बेचैन लोगों की लंबी सूची और कमरे में एक भी वकील नहीं — इससे भरोसा शिविर न खोलने से भी तेज़ी से टूटता है।",
