    "whoItServes": "कार्यक्रम से जुड़ा हर कोई — मदद माँगने वाले सदस्य, मदद देने वाले मददगार, और तालमेल चाहने वाले प्रोजेक्ट चलाने वाले।",
    "whatYoullNeed": "ज़रूरत दर्ज करने की व्यवस्था, मददगारों और संसाधनों की सूची, तालमेल करने वाले, और एक बड़ी साझा डायरेक्टरी। केंद्र के पास पड़ोसियों की ज़िंदगी की नाज़ुक जानकारी रहती है — उतना ही इकट्ठा करें जितना ज़रूरी हो, उसे सँभालकर रखें, और ब्योरा सिर्फ़ उन्हीं को दें जिन्हें मदद करने के लिए वह चाहिए।",
