    "commonPitfalls": "केंद्र दो तरह से मरते हैं: दर्ज गुज़ारिशें भरती जाती हैं पर कोई उन्हें आख़िर तक नहीं पहुँचाता, और बात फैल जाती है कि फ़ोन करने से कुछ नहीं होता; या एक जुझारू शख़्स हर धागा अकेले थामे रहता है और थककर बैठ जाता है, तो कार्यक्रम की याददाश्त ही चली जाती है। हर गुज़ारिश को सचमुच पूरा होने तक देखें, पारियाँ शुरू से बारी-बारी बाँटें, और जितनी जानकारी ज़रूरी लगे उससे कम जमा करें।",
