    "whoItServes": "नशा करने वाले लोग, उनके दोस्त और परिवार, और हर वह शख़्स जिसके सामने कभी ओवरडोज़ हो सकता है — यानी ज़्यादातर मोहल्लों में, कोई भी।",
    "whatYoullNeed": "ओवरडोज़ में क्या करें, इसकी ट्रेनिंग; नैलॉक्सोन का कोई ज़रिया (सरकारी कार्यक्रम, दवा की दुकान, या साथी संस्था); किट का सामान; और बाँटने वाली एक छोटी टोली। सामान बाँटना इलाज नहीं है — बाँटने वाले हर शख़्स को पहले ओवरडोज़ वाली ट्रेनिंग पूरी करनी होगी, और आप क्या साथ रख सकते हैं (टेस्ट स्ट्रिप, सिरिंज) इसका क़ानून जगह-जगह बहुत बदलता है, इसलिए सामान जुटाने से पहले अपनी जगह का क़ानून पक्का कर लें। हर किट में मुश्किल घड़ी और इलाज की स्थानीय हेल्पलाइन छपी रखें।",
